1089	pub(crate) async fn ensure_constitution(
1090	    config: &derrick_config::Config,
1091	    working_dir: &std::path::Path,
1092	    hosts: Arc<HostRegistry>,
1093	) -> Result<(), RunError> {
1094	    let constitution_path = config.guardrails().constitution_path();
1095	    let full_path = working_dir.join(constitution_path);
1096	    if full_path.exists() {
1097	        let contents = std::fs::read_to_string(&full_path).unwrap_or_default();
1098	        if !derrick_adopt::constitution_needs_setup(&contents) {
1099	            return Ok(());
1100	        }
1101	        // File exists but is still an unedited placeholder — treat as missing.
1102	        eprintln!(
1103	            "  {}  Constitution at {} is an unedited template.",
1104	            "⚠".yellow(),
1105	            constitution_path.display()
1106	        );
1107	    } else {
1108	        eprintln!(
1109	            "  {}  No constitution found at {}",
1110	            "⚠".yellow(),
1111	            constitution_path.display()
1112	        );
1113	    }
1114	    eprintln!(
1115	        "     {}",
1116	        "The constitution captures durable rules that the plan reviewer enforces.".bright_black()
1117	    );
1118	    eprintln!(
1119	        "     {}",
1120	        "Describe your project's key rules, constraints, and principles below.".bright_black()
1121	    );
1122	    eprintln!(
1123	        "     {}",
