17	            "failed to canonicalise {}: {source}",
18	            path.display()
19	        ))
20	    })?;
21	    let canonical = serde_json::to_vec(&canonical_json(yaml)).map_err(|source| RunError::Json {
22	        path: path.to_path_buf(),
23	        source,
24	    })?;
25	    let digest = Sha256::digest(canonical);
26	    Ok(format!("sha256:{}", hex_lower(&digest)))
27	}
