29	pub fn canonical_json(value: serde_yaml::Value) -> serde_json::Value {
30	    match value {
31	        serde_yaml::Value::Null => serde_json::Value::Null,
32	        serde_yaml::Value::Bool(value) => serde_json::Value::Bool(value),
33	        serde_yaml::Value::Number(number) => number
34	            .as_i64()
35	            .map(serde_json::Number::from)
36	            .or_else(|| number.as_u64().map(serde_json::Number::from))
37	            .or_else(|| number.as_f64().and_then(serde_json::Number::from_f64))
38	            .map_or(serde_json::Value::Null, serde_json::Value::Number),
39	        serde_yaml::Value::String(value) => serde_json::Value::String(value),
40	        serde_yaml::Value::Sequence(values) => {
41	            serde_json::Value::Array(values.into_iter().map(canonical_json).collect())
42	        }
43	        serde_yaml::Value::Mapping(mapping) => {
44	            let mut object = serde_json::Map::new();
45	            let mut entries = BTreeMap::new();
46	            for (key, value) in mapping {
47	                entries.insert(yaml_key(key), canonical_json(value));
48	            }
49	            for (key, value) in entries {
50	                object.insert(key, value);
51	            }
52	            serde_json::Value::Object(object)
53	        }
54	        serde_yaml::Value::Tagged(tagged) => canonical_json(tagged.value),
55	    }
56	}
